arguments.command:
cd /tmp/vally-eval-trial-ROdO5e && cat > src/CheckoutPricing.Domain/CustomerTier.cs <<'E'
namespace CheckoutPricing.Domain;

public enum CustomerTier
{
    Standard,
    Gold,
}
E
cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class Checkout
{
    public decimal CalculatePayableTotal(CustomerTier tier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.IntegrationTests/GoldDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.IntegrationTests;

public sealed class GoldDiscountAcceptanceTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var total = new Checkout().CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.IntegrationTests 2>&1 | grep -E "error|Failed|Expected|Actual|Assert|Passed!|Failed!" | head -20

